const items = $input.all();
const events = items.map(i => i.json).filter(e => e && e.start);

const today = new Date();
const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const dayName = dayNames[today.getDay()];
const monthName = monthNames[today.getMonth()];
const dateStr = `${dayName}, ${monthName} ${today.getDate()}`;

let message;
if (events.length === 0) {
  message = `\u2600\ufe0f *Good Morning! Today is ${dateStr}*\n\n\u2728 Your schedule is clear today. Enjoy the day!`;
} else {
  const lines = events.map(ev => {
    const startRaw = ev.start.dateTime || ev.start.date;
    let timeStr = 'All day';
    if (ev.start.dateTime) {
      const d = new Date(ev.start.dateTime);
      const hh = String(d.getHours()).padStart(2, '0');
      const mm = String(d.getMinutes()).padStart(2, '0');
      timeStr = `${hh}:${mm}`;
    }
    const title = ev.summary || '(no title)';
    const location = ev.location ? ` (${ev.location})` : '';
    return `\ud83d\udd50 ${timeStr} - ${title}${location}`;
  });
  message = `\u2600\ufe0f *Good Morning! Today is ${dateStr}*\n\n\ud83d\udccb *Your schedule:*\n\n${lines.join('\n')}\n\n_Have a productive day!_`;
}

return [{ json: { content: message, event_count: events.length } }];

return {
  json: {
    timestamp: new Date().toISOString(),
    trigger_type: 'morning',
    command: '/briefing',
    action_completed: 'true',
    response_time_ms: String(Date.now() - new Date($execution.startedAt).getTime()),
    user_confirmed_before_action: 'n/a'
  }
};
